    "documentation": "Generic description of a relationship between parties.",
    "specHtmlUrl": "https://specifications.openehr.org/releases/RM/development/demographic.html#_party_relationship_class",
    "specMarkdownUrl": "https://specifications.openehr.org/releases/RM/development/demographic.md#_party_relationship_class"
