function msg(locale) {
  const code = SUPPORTED_LOCALES.some((l9) => l9.code === locale) ? locale : "en";
  return TABLE2[code];
}
function isIntehrLocale(code) {
  return SUPPORTED_LOCALES.some((l9) => l9.code === code);
}

// src/blockly/i18n/locale.ts
var STORAGE_KEY = "intehrgrator.blockly.hl";
var LOAD_ONCE_BLOCKS_KEY = "intehrgrator.loadOnceBlocks";
var LOAD_ONCE_PROJECT_KEY = "intehrgrator.loadOnceProject";
var LOCALE_RELOAD_AUTOSAVE_KEY = "intehrgrator.localeReloadAutosave";
function detectLocale() {
  try {
    const fromUrl = new URLSearchParams(globalThis.location?.search ?? "").get("hl");
    if (fromUrl && isIntehrLocale(fromUrl)) return fromUrl;
  } catch {
  }
  try {
    const stored = globalThis.localStorage?.getItem(STORAGE_KEY);
    if (stored && isIntehrLocale(stored)) return stored;
  } catch {
  }
  return "en";
}
async function loadBlocklyLocale(locale) {
  const table = await importBlocklyMsg(locale);
  Blockly2.setLocale(table);
  const custom = msg(locale);
  const Msg2 = Blockly2.Msg;
  if (Msg2) {
    Msg2["INTEHR_SOURCE_QUERY"] = custom.SOURCE_QUERY;
    Msg2["INTEHR_SOURCE_QUERY_TOOLTIP"] = custom.SOURCE_QUERY_TOOLTIP;
    Msg2["INTEHR_FOR_EACH_SOURCE_PREFIX"] = custom.FOR_EACH_SOURCE_PREFIX;
    Msg2["INTEHR_FOR_EACH_SOURCE_IN"] = custom.FOR_EACH_SOURCE_IN;
    Msg2["INTEHR_FOR_EACH_SOURCE_NODES"] = custom.FOR_EACH_SOURCE_NODES;
    Msg2["INTEHR_FOR_EACH_SOURCE_DO"] = custom.FOR_EACH_SOURCE_DO;
    Msg2["INTEHR_FOR_EACH_SOURCE_TOOLTIP"] = custom.FOR_EACH_SOURCE_TOOLTIP;
  }
}
async function importBlocklyMsg(locale) {
  const mod = await (async () => {
    switch (locale) {
      case "sv":
        return await Promise.resolve().then(() => (init_sv(), sv_exports));
      case "de":
        return await Promise.resolve().then(() => (init_de(), de_exports));
      case "es":
        return await Promise.resolve().then(() => (init_es(), es_exports));
      case "ca":
        return await Promise.resolve().then(() => (init_ca(), ca_exports));
      case "fr":
        return await Promise.resolve().then(() => (init_fr(), fr_exports));
      default:
        return await Promise.resolve().then(() => (init_en(), en_exports));
    }
  })();
  const anyMod = mod;
  if (anyMod.default && typeof anyMod.default === "object") return anyMod.default;
  return anyMod;
}
function changeLocaleAndReload(locale, workspaceState) {
  try {
    globalThis.localStorage?.setItem(STORAGE_KEY, locale);
    if (workspaceState !== void 0) {
      globalThis.sessionStorage?.setItem(
        LOAD_ONCE_BLOCKS_KEY,
        JSON.stringify(workspaceState)
      );
    }
  } catch {
  }
  const url = new URL(globalThis.location.href);
  url.searchParams.set("hl", locale);
  globalThis.location.href = url.toString();
}
function stashLocaleReloadProject(bundle) {
  try {
    globalThis.sessionStorage?.setItem(LOAD_ONCE_PROJECT_KEY, JSON.stringify(bundle));
    globalThis.sessionStorage?.removeItem(LOAD_ONCE_BLOCKS_KEY);
    globalThis.sessionStorage?.removeItem(LOCALE_RELOAD_AUTOSAVE_KEY);
    return true;
  } catch {
    try {
      globalThis.sessionStorage?.removeItem(LOAD_ONCE_PROJECT_KEY);
    } catch {
    }
    return false;
  }
}
function markLocaleReloadAutosave() {
  try {
    globalThis.sessionStorage?.setItem(LOCALE_RELOAD_AUTOSAVE_KEY, "1");
  } catch {
  }
}
function takeLoadOnceProject() {
  return takeSessionJson(LOAD_ONCE_PROJECT_KEY);
}
function isStashedProjectBundle(value) {
  if (!value || typeof value !== "object") return false;
  const rec = value;
  return typeof rec.version === "number" && Array.isArray(rec.examples) && rec.mapping != null && typeof rec.mapping === "object";
}
function takeLocaleReloadAutosave() {
  try {
    const flag = globalThis.sessionStorage?.getItem(LOCALE_RELOAD_AUTOSAVE_KEY);
    globalThis.sessionStorage?.removeItem(LOCALE_RELOAD_AUTOSAVE_KEY);
    return flag === "1";
  } catch {
    return false;
  }
}
function takeLoadOnceBlocks() {
  return takeSessionJson(LOAD_ONCE_BLOCKS_KEY);
}
function takeSessionJson(key) {
  try {
    const raw = globalThis.sessionStorage?.getItem(key);
    globalThis.sessionStorage?.removeItem(key);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

