      const root = svg2.getSvgRoot?.();
      if (!root) continue;
      const origin = root.getBoundingClientRect();
      const scale = Number(svg2.workspace?.scale ?? 1) || 1;
      const ox = Number(conn.offsetInBlock?.x ?? conn.x ?? 0);
      const oy = Number(conn.offsetInBlock?.y ?? conn.y ?? 0);
      const x6 = origin.left + ox * scale;
      const y7 = origin.top + oy * scale;
